document.addEventListener("DOMContentLoaded", function () {
    const wrap = document.querySelector(".featured-articles-wrap");
    if (!wrap) return;

    const carousel = wrap.querySelector(".featured-articles-carousel");
    const track = wrap.querySelector(".featured-posts-track");
    const prevBtn = wrap.querySelector(".featured-prev");
    const nextBtn = wrap.querySelector(".featured-next");

    let cards = track.querySelectorAll(".featured-post-card");
    const totalOriginal = cards.length;
    if (totalOriginal <= 3) return;

    // Clone first 3 and last 3 cards once to form a permanent buffer zone
    for (let i = 0; i < 3; i++) {
        track.appendChild(cards[i].cloneNode(true));
    }
    for (let i = totalOriginal - 1; i >= totalOriginal - 3; i--) {
        track.insertBefore(cards[i].cloneNode(true), track.firstElementChild);
    }

    cards = track.querySelectorAll(".featured-post-card");
    let currentIndex = 3; 
    let isAnimating = false;

    function getStepSize() {
        const cardRect = cards[0].getBoundingClientRect();
        const style = window.getComputedStyle(track);
        const gap = parseFloat(style.gap) || 28;
        return cardRect.width + gap;
    }

    carousel.style.scrollBehavior = "auto";
    carousel.scrollLeft = currentIndex * getStepSize();

    if (nextBtn) {
        nextBtn.addEventListener("click", function () {
            if (isAnimating) return;
            isAnimating = true;

            currentIndex++;
            carousel.style.scrollBehavior = "smooth";
            carousel.scrollLeft = currentIndex * getStepSize();

            setTimeout(() => {
                if (currentIndex >= totalOriginal + 3) {
                    currentIndex = 3;
                    carousel.style.scrollBehavior = "auto";
                    carousel.scrollLeft = currentIndex * getStepSize();
                }
                isAnimating = false;
            }, 400);
        });
    }

    if (prevBtn) {
        prevBtn.addEventListener("click", function () {
            if (isAnimating) return;
            isAnimating = true;

            currentIndex--;
            carousel.style.scrollBehavior = "smooth";
            carousel.scrollLeft = currentIndex * getStepSize();

            setTimeout(() => {
                if (currentIndex < 3) {
                    currentIndex = totalOriginal + 2;
                    carousel.style.scrollBehavior = "auto";
                    carousel.scrollLeft = currentIndex * getStepSize();
                }
                isAnimating = false;
            }, 400);
        });
    }
});

( () => {
	const lazyloadRunObserver = () => {
		const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
		const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
			entries.forEach( ( entry ) => {
				if ( entry.isIntersecting ) {
					let lazyloadBackground = entry.target;
					if( lazyloadBackground ) {
						lazyloadBackground.classList.add( 'e-lazyloaded' );
					}
					lazyloadBackgroundObserver.unobserve( entry.target );
				}
			});
		}, { rootMargin: '200px 0px 200px 0px' } );
		lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
			lazyloadBackgroundObserver.observe( lazyloadBackground );
		} );
	};
	const events = [
		'DOMContentLoaded',
		'elementor/lazyload/observe',
	];
	events.forEach( ( event ) => {
		document.addEventListener( event, lazyloadRunObserver );
	} );
} )();
